        "id": "KIM-TYT-K07-T03-S05",
        "question": "Kütlece %10'luk tuzlu su çözeltisinden 250 gram alınarak içerisine 50 gram daha **saf tuz** eklenip tamamen çözülmesi sağlanıyor.\nSon çözeltinin kütlece tuz yüzdesi kaçtır?",
