        "solution": "Hacim 200 mL'den 400 mL'ye (2 katına) çıkmıştır. İçindeki alkol miktarı sabit kaldığı için hacimce yüzdesi yarıya düşer. $80 / 2 = 40^\\circ$. (C)."
