        "question": "Bir fabrika atık suyunda siyanür ($CN^-$) derişimi 0.5 ppm olarak ölçülmüştür.\nBuna göre 4000 kg atık su havuzunda toplam kaç **gram** siyanür iyonu bulunur?\n(1 kg = 1000 gram = 1.000.000 mg)",
