        "question": "Saf su, Hacimce %40'lık Etil Alkol çözeltisi ve Hacimce %80'lik Etil Alkol çözeltisi eşit hacimlerde karıştırılıyor.\nOluşan son karışımın hacimce alkol yüzdesi kaçtır?",
