        "question": "100 gram saf suda 0.1 mol glikoz (şeker) çözüldüğünde kaynamaya başlama sıcaklığı saf suya göre a °C kadar yükseliyor.\nBuna göre 100 gram suda 0.2 mol glikoz çözülürse, kaynamaya başlama noktası kaç °C yükselir?",
