        "question": "Naftalin ve İyot katılarından oluşan bir karışımı ayırmak için;\nI. Suya atma\nII. Isıtma (Süblimleşme)\nIII. Karbontetraklorür ($CCl_4$) sıvısına atma\nyöntemlerinden hangileri **uygun değildir?**\n(Not: Naftalin apolar, İyot apolardır. Naftalin ve İyot süblimleşebilen katılardır).",
