        "question": "Hacimce %60'lık etil alkol çözeltisi ile hacimce %20'lik etil alkol çözeltisi hangi hacim oranlarında ($V_1 / V_2$) karıştırılırsa, oluşan son karışımın hacimce alkol yüzdesi %30 olur?\n(1. çözelti $V_1$, 2. çözelti $V_2$ hacmindedir).",
