        "difficulty": "hard",
        "solution": "Pearson karesi ile:\n60 ile 20'yi karıştırıp 30 elde etmek istiyoruz.\n$|60 - 30| = 30$ pay 20'liğe aittir.\n$|20 - 30| = 10$ pay 60'lığa aittir.\nYani %60'lıktan 10 V (veya 1 V) alırsak, %20'likten 30 V (veya 3 V) almalıyız.\n$V_1 (\\%60'lık) / V_2 (\\%20'lik) = 10 / 30 = 1 / 3$.\nDenklemle: $60 V_1 + 20 V_2 = 30(V_1 + V_2) \\Rightarrow 30 V_1 = 10 V_2 \\Rightarrow V_1 / V_2 = 1 / 3$. (C)."
