        "id": "KIM-TYT-K07-T19-S03",
        "question": "Aşağıda verilen karışımları ayırma yöntemlerinin hangisinde, maddenin hal değişimi (katı $\\rightarrow$ sıvı, sıvı $\\rightarrow$ gaz vb.) **gerçekleşmez?**",
