        "question": "İçerisinde kütlece %20 oranında $NaCl$ bulunan 400 gram tuzlu suyun, kütlece %50 oranında $NaCl$ içeren bir çözeltiye dönüşebilmesi için aşağıdakilerden hangisi uygulanmalıdır?",
