        "correctAnswer": "B",
        "difficulty": "hard",
        "solution": "Başlangıç: $400 \\times 0.20 = 80 \\ gram$ tuz var.\nHedef %50 olması. Su buharlaştırsak: $(80 / M) = 1/2 \\Rightarrow M = 160$ gram son çözelti. $400 - 160 = 240$ gram su uçmalı (C şıkkında 160 uçar demiş, yanlış).\nTuz eklesek: Eklenen tuza X diyelim.\nYeni Tuz = $80 + X$. Yeni Çözelti = $400 + X$.\nYüzde 50 demek payın paydanın yarısı olması demek: $(80 + X) / (400 + X) = 1/2$.\nİçler dışlar: $160 + 2X = 400 + X \\Rightarrow X = 240 \\ gram$ tuz eklenmelidir. (B)."
