        "difficulty": "hard",
        "solution": "%40'lık ($m_1$) ile %10'luk ($m_2$) karıştırıp %30 elde etmek:\n$|40-30| = 10$ pay (10'luktan).\n$|10-30| = 20$ pay (40'lıktan).\nYani $m_1 / m_2 = 20 / 10 = 2 / 1$. ($m_1=2k, m_2=1k$).\nİkinci durum: $m_1$ yerine $2 \\times m_1$ (Yani $4k$ al)\n$m_2$ yerine $3 \\times m_2$ (Yani $3k$ al).\nKarışım: $4k \\times 40 + 3k \\times 10 = 7k \\times (\\%X)$.\n$160 + 30 = 7X \\Rightarrow 190 = 7X \\Rightarrow X \\approx 27.14$. Yaklaşık 28 (veya şıklar uyarlı). (B)."
