        "question": "Havada bulunan ve solunması tehlikeli olan çok ince toz partiküllerinin (Örn: PM2.5, PM10) derişimi genellikle $\\mu g/m^3$ veya **ppm** olarak ifade edilir.\n1 milyon litre ($1.000 \\ m^3$) havada, 2 Litre hacminde zararlı gaz (Örn: Karbonmonoksit) bulunuyorsa, bu gazın derişimi hacimce kaç ppm'dir?",
