        "id": "KIM-TYT-K07-T26-S07",
        "question": "Büyük şehirlerde, özellikle sanayi tesislerinin yoğun olduğu bölgelerde bacalardan ve egzozlardan çıkan katı partiküllerin, dumanın hava (gaz) içerisinde asılı kalmasıyla oluşan karışım türüne ne ad verilir?",
