        "id": "KIM-TYT-K07-T26-S10",
        "question": "Deniz seviyesinde saf suyun içine bir miktar şeker eklenip tamamen çözülüyor.\nSıcaklık - Zaman grafiği incelendiğinde;\n- Suyun $100^\\circ C$'de kaynadığı, \n- Şeker eklendikten sonra kaynamanın $102^\\circ C$'de başladığı,\n- Kaynama süresince sıcaklığın bir süre artıp sonra sabitlendiği görülüyor.\nKaynama süresince sıcaklığın önce artıp (örneğin 104°C'ye çıkıp) **sonra sabit kalmasının** kimyasal nedeni aşağıdakilerden hangisidir?",
