        "solution": "1. Kaptaki $NaCl$ (Mol kütlesi 58.5) ve 2. Kaptaki Glikoz (Mol kütlesi 180).\nKütleler (m) eşit. Mol = $m / M_A$.\n$NaCl$'nin molü daha büyüktür ($m / 58.5 > m / 180$). Üstelik $NaCl$ suda 2 iyon verir.\nBu yüzden 1. kaptaki toplam tanecik sayısı (molü), 2. kaptan çok daha fazladır.\nTanecik sayısı çok olduğu için 1. kabın kaynama noktası DAHA YÜKSEKTİR (I KESİN doğru).\nKaynama noktası yüksek olan 1. kabın buhar basıncı DAHA DÜŞÜKTÜR. II. öncül 2'ninki daha düşüktür diyor, YANLIŞTIR.\n$NaCl$ tuz olduğu için sulu çözeltisi elektrik akımını iletir (III doğru). (C)."
