        "question": "10 ppm ($mg/kg$) kurşun ($Pb^{2+}$) içeren 200 gramlık bir atık su numunesindeki kurşun iyonları, laboratuvarda kimyasal bir madde (sülfür) ile tamamen çöktürülüyor.\nÇöken kurşun bileşiğinden değil, sadece çöken kurşunun kütlesi üzerinden hesap yapıldığında; çöken kurşun miktarı kaç **miligramdır?**",
