        "solution": "1. Çözeltide Tuz: $100 \\times 0.30 = 30 \\ g$.\n2. Çözeltide Tuz: $200 \\times 0.60 = 120 \\ g$.\nToplam Tuz = $30 + 120 = 150 \\ g$.\nŞu anki Toplam Çözelti Kütlesi = $100 + 200 = 300 \\ g$.\nDerişimin %40 olmasını istiyoruz.\n$150 / (300 + X) = 40 / 100 = 2 / 5$ (Burada X, eklenecek saf sudur).\n$750 = 600 + 2X \\Rightarrow 2X = 150 \\Rightarrow X = 75 \\ gram$ su eklenmelidir. (B)."
