        "question": "150 gram suya 50 gram sofra tuzu ($NaCl$) katılarak bir çözelti hazırlanıyor. Ancak tüm tuz çözünmüyor, 10 gramı dipte katı olarak kalıyor.\nBuna göre bu sistemdeki (sıvı fazdaki) **Kütlece Yüzde Derişim** kaçtır?",
