        "solution": "1. Kaptaki Şeker = $200 \\times 0.25 = 50 \\ gram$.\nSaf Su = Şeker 0 gram.\nEklenen Şeker = 50 gram (Tamamı Şeker).\nEklenen Çözeltide Şeker = $50 \\times 0.40 = 20 \\ gram$.\nTOPLAM ŞEKER = $50 + 0 + 50 + 20 = 120 \\ gram$.\nTOPLAM KÜTLE = $200 + 100 + 50 + 50 = 400 \\ gram$.\nSon Yüzde = $(120 / 400) \\times 100 = 120 / 4 = \\%30$. (C)."
