        "correctAnswer": "B",
        "difficulty": "hard",
        "solution": "Çözünürlük 25 g X / 100 g su.\nI. 200 g su, 100g suyun 2 katıdır. O halde 25'in 2 katı olan 50 gram X çözerse TAM DOYMUŞ olur. (I doğru).\nII. 100 g su + 25 g X = 125 g (Doygun çözelti).\n125 g doygun çözeltinin 25 gramı X'tir.\nSoruda 400 g doygun çözelti deniyor ($400 / 125 = 3.2$ katı).\nX miktarı = $25 \\times 3.2 = 80 \\ gram$ X vardır. (II doğru).\nIII. Kütlece Yüzde = (Çözünen / Toplam) x 100 = $(25 / 125) \\times 100 = 100 / 5 = \\%20$'dir. (%25 DEĞİLDİR). (III yanlış). Cevap I ve II. (B)."
